import {escapeHtml as esc,icon} from './components.js';
import {price,percentage,time,modeLabels,dailyQuoteMeta} from './data.js';
import {selectPeriod} from './stock-chart-model.js';
import {createPreviewLoader,previewKey,rankingPreviewChoice} from './stock-preview-model.js';

export function mountStockPreview(root,{onSelection,initialPeriod='3m',onPeriod,loadChartModule=()=>import('/vendor/lightweight-charts/lightweight-charts.mjs')}={}){
 const life=new AbortController();let libraryPending=null;
 let refreshedAt=0,current=null,period=['1m','3m','1y','all'].includes(initialPeriod)?initialPeriod:'3m',chart,series,volumeSeries,lib,context='',rows=[],selected=null,chartKey=null,disposed=false;
 const choices=new Map();
 root.innerHTML=`<div class="panel-heading"><div class="title-group"><h2>종목 미리보기</h2><span class="preview-daily">일봉</span></div><a class="preview-detail" data-nav hidden>상세 보기 ${icon('arrow')}</a></div><div class="preview-identity"><strong>순위 불러오는 중</strong><small></small></div><div class="preview-quote"><b>—</b><span></span></div><p class="preview-quote-time"></p><div class="preview-periods" role="group" aria-label="미리보기 조회 기간">${[['1m','1개월'],['3m','3개월'],['1y','1년'],['all','전체']].map(([id,label])=>`<button data-preview-period="${id}" aria-pressed="${id===period}">${label}</button>`).join('')}</div><div class="preview-plot"><div class="preview-canvas"></div><div class="preview-state" role="status"></div></div><div class="preview-readout"></div><div class="panel-foot"><span class="preview-source">종목을 선택하면 일봉을 표시합니다.</span></div><p class="preview-attribution"><a href="https://www.tradingview.com/" target="_blank" rel="noopener noreferrer">TradingView Lightweight Charts™</a> · Copyright (с) 2025 TradingView, Inc.</p>`;
 const $=s=>root.querySelector(s),loader=createPreviewLoader({onState:render});
 function quote(stock,feed){$('.preview-identity strong').textContent=stock?.name||'종목을 선택해 주세요';$('.preview-identity small').textContent=stock?stock.ticker+' · '+(stock.market==='KR'?'국내':'미국')+' · '+stock.currency:'';$('.preview-quote b').textContent=stock?price(stock):'—';const change=$('.preview-quote span');change.textContent=stock?(stock.mode==='monthly_close'?'월 누적 ':'')+percentage(stock.changePct):'';change.className=stock?.changePct>0?'up':stock?.changePct<0?'negative':'neutral-text';$('.preview-quote-time').textContent=stock?.mode==='monthly_close'?'기준일 종가 · '+stock.baseDate:stock?.baseDate?dailyQuoteMeta(stock):stock?.asOf?(modeLabels[stock.mode||feed?.mode]||'제공 시세')+' · '+(stock.asOfKind==='received'?'조회 ':'기준 ')+time(stock.asOf,true):'';const link=$('.preview-detail');link.hidden=!stock;link.href=stock?'/stock/'+stock.market+'/'+encodeURIComponent(stock.id||stock.ticker):'#';}
 function range(){if(!chart||!current?.model?.bars.length)return;const all=current.model.bars,selected=selectPeriod(all,period).items;chart.timeScale().setVisibleLogicalRange({from:all.length-selected.length-.8,to:all.length+.2});}
 function render(data){
  if(data.status!=='loading')refreshedAt=Date.now();
  current=data;quote(data.stock,data.feed);root.setAttribute('aria-busy',String(data.status==='loading'));$('.preview-plot').dataset.state=data.status;
  const state=$('.preview-state'),ready=data.status==='ready';state.hidden=ready;
  state.innerHTML=ready?'':data.status==='loading'?'<span class="preview-spinner"></span><strong>일봉 불러오는 중</strong>':data.status==='error'?'<strong>연결 오류 · 차트를 불러오지 못했습니다</strong><button data-preview-retry>다시 시도</button>':'<strong>일봉 데이터 없음</strong><span>'+esc(data.message||'확보된 일봉이 없습니다.')+'</span>';
  $('.preview-canvas').hidden=!ready;$('.preview-readout').textContent='';
  $('.preview-source').textContent=data.model?(data.stale?'마지막 저장 자료 · ':'')+data.model.source+' · 일봉 기준 '+(data.model.baseDate||'없음')+(data.model.receivedAt?' · 동기화 '+time(data.model.receivedAt,true):''):data.status==='loading'?'':'실제 제공된 일봉만 표시합니다.';
  if(!ready)return;if(!lib){if(!libraryPending)libraryPending=loadChartModule().then(l=>{if(disposed)return;lib=l;if(current?.status==='ready')render(current);}).catch(()=>{if(!disposed)render({...current,status:'error'});}).finally(()=>{libraryPending=null;});return;}
  const bars=data.model.bars,candles=bars.every(b=>b.ohlc),type=candles?'candles':'line';
  if(!chart||chartKey!==type){chart?.remove();chart=lib.createChart($('.preview-canvas'),{autoSize:true,layout:{background:{type:'solid',color:'#fff'},textColor:'#8B97A8',fontFamily:'Pretendard, sans-serif',fontSize:11},grid:{vertLines:{visible:false},horzLines:{color:'#F0F3F7'}},rightPriceScale:{borderVisible:false,minimumWidth:60,alignLabels:true,scaleMargins:{top:.1,bottom:.23}},timeScale:{borderColor:'#E5EAF0',timeVisible:false,rightOffset:1},localization:{locale:'ko-KR',dateFormat:'yyyy-MM-dd'},handleScroll:{mouseWheel:false,pressedMouseMove:true,horzTouchDrag:true,vertTouchDrag:false},handleScale:{mouseWheel:false,pinch:true,axisPressedMouseMove:false},crosshair:{mode:lib.CrosshairMode.Normal}});series=chart.addSeries(candles?lib.CandlestickSeries:lib.LineSeries,{upColor:'#D84B52',downColor:'#3479D4',wickUpColor:'#D84B52',wickDownColor:'#3479D4',borderVisible:false,color:'#087f73',lineWidth:2,priceLineVisible:false,lastValueVisible:true});chart.subscribeCrosshairMove(e=>{const bar=current?.model?.bars.find(b=>b.date===e.time)||current?.model?.bars.at(-1);readout(bar);});volumeSeries=chart.addSeries(lib.HistogramSeries,{priceFormat:{type:'volume'},priceScaleId:'volume',priceLineVisible:false,lastValueVisible:false});chart.priceScale('volume').applyOptions({scaleMargins:{top:.85,bottom:0},visible:false});chartKey=type;}
  series.applyOptions({priceFormat:{type:'price',precision:data.stock.currency==='KRW'?0:2,minMove:data.stock.currency==='KRW'?1:.01}});
  volumeSeries.setData(bars.filter(b=>Number.isFinite(b.volume)).map(b=>({time:b.date,value:b.volume,color:b.close>=b.open?'#D84B5250':'#3479D450'})));series.setData(bars.map(b=>candles?{time:b.date,open:b.open,high:b.high,low:b.low,close:b.close}:{time:b.date,value:b.close}));range();readout(bars.at(-1));
 }
 function readout(bar){$('.preview-readout').textContent=bar?bar.date+' · 종가 '+price({price:bar.close,currency:current.stock.currency})+(Number.isFinite(bar.volume)?' · 거래량 '+bar.volume.toLocaleString('ko-KR')+'주':''):'';}
 function choose(stock,immediate=false,manual=true){if(disposed||!stock)return;const key=previewKey(stock);choices.set(context,{key,manual});if(selected===key&&current){quote(stock.mode==='monthly_close'?current.stock:stock,current.feed);return;}selected=key;onSelection?.(key);loader.select(stock,{immediate});}
 root.addEventListener('click',e=>{const p=e.target.closest('[data-preview-period]');if(p){period=p.dataset.previewPeriod;onPeriod?.(period);root.querySelectorAll('[data-preview-period]').forEach(b=>b.setAttribute('aria-pressed',String(b===p)));range();}if(e.target.closest('[data-preview-retry]'))loader.retry();},{signal:life.signal});
 return {setRows(next,nextContext){if(disposed)return;rows=next;const changed=context!==nextContext;context=nextContext;if(!rows.length){selected=null;loader.cancel();render({status:'empty',message:'조건에 맞는 종목이 없습니다.'});return;}const {stock,manual}=rankingPreviewChoice(rows,choices.get(context));if(selected===previewKey(stock)&&current?.status!=='loading'&&!loader.isFresh(stock)&&Date.now()-refreshedAt>300000)loader.select(stock,{immediate:true});else choose(stock,changed||!selected,manual);},select:choose,getSelected:()=>selected,getPeriod:()=>period,setPeriod(next){if(disposed||!['1m','3m','1y','all'].includes(next))return;period=next;root.querySelectorAll('[data-preview-period]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.previewPeriod===period)));range();},clear(message='관심종목을 선택해 주세요'){if(disposed)return;loader.cancel();selected=null;current=null;render({status:'empty',message});},loading(){if(disposed)return;loader.cancel();selected=null;render({status:'loading'});},destroy(){if(disposed)return;disposed=true;life.abort();loader.destroy();chart?.remove();chart=null;current=null;rows=[];choices.clear();}};
}
